def add_disposal(raw, support, statements):
    text = low(raw)
    triggers = trigger_terms(text)
    if not triggers:
        return
    do_return = has_return_action(text)
    do_destroy = has_destroy_action(text)
    if not do_return and (not do_destroy):
        return
    info = information_scope(text)
    if do_return and do_destroy:
        action = ['action_alternative', ['return_to', info, ['disclosing_party']], ['destroy', info]]
    elif do_return:
        action = ['return_to', info, ['disclosing_party']]
    else:
        action = ['destroy', info]
    add_statement(statements, ['disposal_obligation', actor_for(text), action, trigger_value(triggers), ['no_exceptions']], support)

def add_retention(raw, uid, statements):
    text = low(raw)
    info = information_scope(text)
    actor = actor_for(text)
    if has_any(text, ['entitled to retain', 'may retain', 'may maintain a single copy', 'permitted to retain']):
        add_statement(statements, ['retention_permission', actor, info, ['after_disposal'], ['retention_condition', raw]], [uid])
    if has_any(text, ['without retaining any copies', 'no copies, electronic or otherwise', 'no copies or records thereof shall be retained', 'no copy shall be retained']):
        add_statement(statements, ['retention_prohibition', actor, info, ['after_disposal']], [uid])
    if has_any(text, ['not to make or retain copy', 'shall not retain any copy', 'must not retain any copy', 'no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        add_statement(statements, ['absolute_retention_prohibition', actor, info], [uid])

def term_has(term, name):
    todo = [term]
    while todo:
        item = todo.pop()
        if isinstance(item, list) and item:
            if item[0] == name:
                return True
            i = 1
            while i < len(item):
                if isinstance(item[i], list):
                    todo.append(item[i])
                i += 1
    return False

def _scope_previous_source(inputs, premises):
    spans = inputs.get('source_spans', [])
    statements = []
    source_output = inputs.get('source_output', {})
    if isinstance(source_output, dict):
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                add_statement(statements, row.get('term'), row.get('support_ids', []))
    texts = []
    ids = []
    for span in spans:
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw, uid, statements)
        parse_disclosure(raw, [uid], statements)
        add_disposal(raw, [uid], statements)
        add_retention(raw, uid, statements)
    i = 0
    while i < len(texts):
        current = low(texts[i])
        if current.endswith(':') and has_any(current, ['may disclose', 'do not apply to the disclosure', 'shall be handled as follows']) or (has_any(current, ['return of confidential information', 'shall be returned', 'returned to']) and (not trigger_terms(current))):
            j = i + 1
            while j < len(texts) and j <= i + 4:
                combined = ' '.join(texts[i:j + 1])
                support = ids[i:j + 1]
                parse_disclosure(combined, support, statements)
                add_disposal(combined, support, statements)
                j += 1
        triggers = trigger_terms(current)
        if triggers and (not has_return_action(current)) and (not has_destroy_action(current)):
            floor = max(0, i - 3)
            j = i - 1
            while j >= floor:
                previous = low(texts[j])
                if has_return_action(previous) or has_destroy_action(previous):
                    add_disposal(texts[j] + ' ' + texts[i], [ids[j], ids[i]], statements)
                    break
                j -= 1
        i += 1
    definitions = False
    unresolved = []
    for row in statements:
        if isinstance(row.get('term'), list) and row.get('term') and (row.get('term')[0] == 'define_representative'):
            definitions = True
    if not definitions:
        for row in statements:
            term = row.get('term')
            if term_has(term, 'representatives_of'):
                unresolved.append('Representatives membership is used by an operative rule but is not defined in the current source output.')
                break
    return {'statements': statements, 'complete': len(unresolved) == 0, 'unresolved': unresolved}

def atoms_low(value):
    if not isinstance(value, str):
        value = str(value)
    return value.casefold().strip()

def atoms_unique(values):
    out = []
    for value in values:
        if value not in out:
            out.append(value)
    return out

def atoms_add(out, term, support_ids):
    support = atoms_unique(support_ids)
    for row in out:
        if row.get('term') == term and row.get('support_ids', []) == support:
            return
    out.append({'term': term, 'support_ids': support})

def atoms_label_at(text, pos):
    if pos < 0 or pos >= len(text) or (not text[pos].isdigit()):
        return None
    if pos > 0 and (not text[pos - 1].strip() == ''):
        return None
    j = pos
    while j < len(text) and (text[j].isdigit() or text[j] == '.'):
        j += 1
    token = text[pos:j]
    while token.endswith('.'):
        token = token[:-1]
    if not token:
        return None
    parts = token.split('.')
    for part in parts:
        if not part or not part.isdigit():
            return None
    if len(parts) < 2 and pos != 0:
        return None
    if j < len(text) and (not text[j].strip() == ''):
        return None
    return [token, j]

def atoms_parent_key(label, known):
    if not isinstance(label, str) or '.' not in label:
        return None
    candidate = label.rsplit('.', 1)[0]
    if candidate in known:
        return candidate
    return None

def atoms_find_any(text, phrases):
    best = -1
    for phrase in phrases:
        pos = text.find(phrase)
        if pos >= 0 and (best < 0 or pos < best):
            best = pos
    return best

def atoms_trigger_value(raw):
    text = atoms_low(raw)
    items = []
    if 'termination of service' in text or 'service terminates' in text or 'service termination' in text:
        items.append(['service_termination'])
    if 'termination of this agreement' in text or 'expiration of this agreement' in text or 'expiration or termination of this agreement' in text:
        items.append(['agreement_termination'])
    if 'termination of the project' in text or 'expiration of the project' in text or 'termination or expiration of the project' in text or ('expiration or other termination of the project' in text):
        items.append(['project_termination'])
    if 'termination of the business relationship' in text or 'termination of the working relationship' in text or 'termination/expiration of the business relation' in text:
        items.append(['relationship_termination'])
    if 'business relationship is not entered' in text or 'relationship is not entered' in text or 'fail to enter into a business relationship' in text:
        items.append(['relationship_nonformation_deadline'])
    if 'completion of the purpose' in text:
        items.append(['purpose_completion'])
    if 'upon demand' in text or 'upon request' in text or 'if requested' in text or ('so requests' in text) or ('on the request' in text) or ('at the request' in text):
        items.append(['request_by', ['disclosing_party']])
    items = atoms_unique(items)
    if not items:
        return None
    value = items[0]
    i = 1
    while i < len(items):
        value = ['trigger_alternative', value, items[i]]
        i += 1
    return value

def atoms_material_value(raw):
    text = atoms_low(raw)
    if 'any and all materials' in text or 'all materials' in text:
        base = ['source_stated_materials', raw]
        return ['source_bounded_material', base, raw]
    has_info = 'confidential information' in text or 'such information' in text or 'all information' in text or ('information disclosed' in text)
    has_copies = 'copy' in text or 'copies' in text or 'reproduction' in text
    has_derivatives = 'note' in text or 'abstract' in text or 'analysis' in text or ('summary' in text) or ('extract' in text) or ('derivative' in text)
    if has_info:
        base = ['confidential_information']
        if has_copies:
            base = ['information_bundle', base, ['copies_of', ['confidential_information']]]
        if has_derivatives:
            base = ['information_bundle', base, ['derivative_materials_of', ['confidential_information']]]
        return ['source_bounded_material', base, raw]
    if has_copies:
        base = ['copies_of', ['confidential_information']]
        if has_derivatives:
            base = ['information_bundle', base, ['derivative_materials_of', ['confidential_information']]]
        return ['source_bounded_material', base, raw]
    return None

def atoms_recipient_terms(raw):
    text = atoms_low(raw)
    direct = ['receiving_party']
    controlled = ['controlled_entities_of', ['receiving_party']]
    items = []
    employee_owner = direct
    if 'companies directly or indirectly owned or controlled' in text or 'entities controlled by' in text or 'under common control' in text:
        employee_owner = controlled
    if 'employee' in text or 'staff' in text or 'personnel' in text:
        items.append(['employees_of', employee_owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of', direct])
    if 'consultant' in text:
        items.append(['consultants_of', direct])
    if 'legal adviser' in text or 'legal advisor' in text or 'attorney' in text or ('legal counsel' in text):
        items.append(['legal_advisors_of', direct])
    if 'financial adviser' in text or 'financial advisor' in text:
        items.append(['financial_advisors_of', direct])
    if ('professional adviser' in text or 'professional advisor' in text or ' advisors' in text or (' advisers' in text)) and (not ('legal adviser' in text or 'legal advisor' in text or 'financial adviser' in text or ('financial advisor' in text))):
        items.append(['professional_advisors_of', direct])
    if 'agent' in text:
        items.append(['agents_of', direct])
    if 'accountant' in text:
        items.append(['accountants_of', direct])
    if 'director' in text:
        items.append(['directors_of', direct])
    if 'officer' in text or 'official' in text:
        items.append(['officers_of', direct])
    if not items and 'representative' in text:
        items.append(['representatives_of', direct])
    return atoms_unique(items)

def atoms_condition_terms(raw):
    text = atoms_low(raw)
    out = []
    if 'need to know' in text or 'need-to-know' in text or 'bona fide need' in text:
        out.append(['need_to_know', raw])
    if 'strictly necessary' in text or 'extent necessary' in text or 'disclosure is necessary' in text or ('reasonably necessary' in text) or ('necessary for the permitted purpose' in text):
        out.append(['extent_necessary', raw])
    if 'written confidentiality agreement' in text or 'subject to the provisions of this confidentiality agreement' in text or 'bound by obligations of confidentiality' in text or ('obligated to protect' in text) or ('treat the confidential information as confidential' in text):
        out.append(['confidentiality_bound', raw])
    return atoms_unique(out)

def atoms_reference_labels(raw):
    text = atoms_low(raw)
    out = []
    start = 0
    while start < len(text):
        pos = text.find('clause ', start)
        if pos < 0:
            break
        i = pos + 7
        j = i
        while j < len(text) and (text[j].isdigit() or text[j] == '.'):
            j += 1
        token = text[i:j]
        while token.endswith('.'):
            token = token[:-1]
        if token and '.' in token:
            parts = token.split('.')
            valid = True
            for part in parts:
                if not part.isdigit():
                    valid = False
            if valid and token not in out:
                out.append(token)
        start = max(j, pos + 8)
    return out

def atoms_has_target_trigger(action, parents, triggers):
    target = action.get('action')
    if target in triggers:
        return True
    target = action.get('clause')
    while target is not None:
        if target in triggers:
            return True
        target = parents.get(target)
    return False

def acquire_atoms(inputs, premises):
    spans = []
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
    records = []
    order = 0
    for span in spans:
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        for record in atoms_split_unit(raw, uid):
            record['order'] = order
            order += 1
            records.append(record)
    known = {}
    for record in records:
        known[record.get('key')] = record
    parents = {}
    for key in known.keys():
        parent = atoms_parent_key(key, known)
        if parent is not None:
            parents[key] = parent
    out = []
    unresolved = []
    active = set()
    disposal = []
    connectors = []
    triggers = set()
    disclosure = []
    for record in records:
        raw = record.get('text', '')
        text = atoms_low(raw)
        key = record.get('key')
        scope = atoms_scope_key(key, known)
        return_pos = atoms_find_any(text, ['promptly return', 'shall return', 'return all', 'return any', 'returned to', 'return to'])
        destroy_pos = atoms_find_any(text, ['destroy or delete', 'destroy or permanently erase', 'promptly destroy', 'shall destroy', 'shall be destroyed', 'destroy all', 'permanently erase', 'delete all'])
        action_positions = []
        if return_pos >= 0:
            action_positions.append(['return', return_pos])
        if destroy_pos >= 0:
            action_positions.append(['destroy', destroy_pos])
        action_positions = sorted(action_positions, key=atoms_lifted_sort_key_0)
        if action_positions:
            active.add(key)
            first = action_positions[0][1]
            prefix = raw[:first]
            prefix_trigger = atoms_trigger_value(prefix)
            if prefix_trigger is not None:
                atoms_add(out, ['source_trigger_atom', scope, key, prefix_trigger, prefix], [record.get('uid')])
                triggers.add(key)
            i = 0
            while i < len(action_positions):
                kind = action_positions[i][0]
                start = action_positions[i][1]
                stop = action_positions[i + 1][1] if i + 1 < len(action_positions) else len(raw)
                segment = raw[start:stop].strip()
                action_key = key + '#' + kind
                atoms_add(out, ['source_action_atom', scope, action_key, key, kind, segment], [record.get('uid')])
                material = atoms_material_value(segment)
                if material is not None:
                    atoms_add(out, ['source_material_atom', scope, action_key, material, segment], [record.get('uid')])
                else:
                    atoms_add(out, ['source_unresolved_qualifier_atom', scope, action_key, 'material', segment], [record.get('uid')])
                    unresolved.append('material unresolved for ' + action_key)
                local_trigger = atoms_trigger_value(segment)
                if local_trigger is not None:
                    atoms_add(out, ['source_trigger_atom', scope, action_key, local_trigger, segment], [record.get('uid')])
                    triggers.add(action_key)
                if kind == 'destroy' and ('expressly authorised in writing' in text or 'expressly authorized in writing' in text or 'written authorisation' in text or ('written authorization' in text)):
                    atoms_add(out, ['source_authorization_atom', scope, action_key, raw], [record.get('uid')])
                if kind == 'destroy' and 'made by the receiving party' in text:
                    atoms_add(out, ['source_copy_owner_atom', scope, action_key, ['receiving_party'], 'made by the receiving Party'], [record.get('uid')])
                if kind == 'destroy' and 'anyone to whom the receiving party has supplied copies' in text:
                    holder = ['source_designated_participant', 'anyone to whom the receiving Party has supplied copies']
                    atoms_add(out, ['source_copy_owner_atom', scope, action_key, holder, 'such copies and any further copies made by them'], [record.get('uid')])
                disposal.append({'scope': scope, 'action': action_key, 'clause': key, 'kind': kind, 'uid': record.get('uid'), 'order': record.get('order')})
                i += 1
            if len(action_positions) > 1:
                left = key + '#' + action_positions[0][0]
                right = key + '#' + action_positions[1][0]
                middle = text[action_positions[0][1]:action_positions[1][1]]
                connector = 'or' if ' or' in middle else 'and' if ' and' in middle else 'unresolved'
                atoms_add(out, ['source_connector_atom', scope, left, right, connector, raw], [record.get('uid')])
                connectors.append([scope, left, right, connector])
                if connector == 'unresolved':
                    unresolved.append('action connector unresolved for ' + key)
        recipients = atoms_recipient_terms(raw)
        direct_permission = 'may disclose' in text or 'may be disclosed' in text or 'only to disclose' in text or ('disclosed only to' in text) or ('restrict access' in text) or ('restrict disclosure' in text) or ('except in confidence to' in text)
        inherited_permission = False
        parent = parents.get(key)
        while parent is not None:
            ptext = atoms_low(known[parent].get('text', ''))
            if 'may disclose' in ptext or 'may be disclosed' in ptext:
                inherited_permission = True
                break
            parent = parents.get(parent)
        if recipients and (direct_permission or inherited_permission) and ('confidential information' in text or inherited_permission):
            active.add(key)
            action_key = key + '#disclose'
            atoms_add(out, ['source_disclosure_action_atom', scope, action_key, key, raw], [record.get('uid')])
            for recipient in recipients:
                atoms_add(out, ['source_recipient_atom', scope, action_key, recipient, raw], [record.get('uid')])
            for condition in atoms_condition_terms(raw):
                atoms_add(out, ['source_condition_atom', scope, action_key, condition, raw], [record.get('uid')])
            disclosure.append({'scope': scope, 'action': action_key, 'clause': key, 'uid': record.get('uid')})
    changed = True
    while changed:
        changed = False
        for key in list(active):
            parent = parents.get(key)
            if parent is not None and parent not in active:
                active.add(parent)
                changed = True
    for key in sorted(active):
        record = known.get(key)
        if record is None:
            continue
        scope = atoms_scope_key(key, known)
        atoms_add(out, ['source_clause_atom', scope, key, record.get('text', '')], [record.get('uid')])
        parent = parents.get(key)
        if parent is not None:
            atoms_add(out, ['source_clause_parent_atom', scope, parent, key], [known[parent].get('uid'), record.get('uid')])
        has_disposal = False
        for action in disposal:
            if action.get('clause') == key:
                has_disposal = True
        if not has_disposal:
            trigger = atoms_trigger_value(record.get('text', ''))
            if trigger is not None:
                atoms_add(out, ['source_trigger_atom', scope, key, trigger, record.get('text', '')], [record.get('uid')])
                triggers.add(key)
        for target in atoms_reference_labels(record.get('text', '')):
            atoms_add(out, ['source_reference_atom', scope, key, target, record.get('text', '')], [record.get('uid')])
            if target not in known:
                atoms_add(out, ['source_unresolved_qualifier_atom', scope, key, 'unresolved clause reference ' + target, record.get('text', '')], [record.get('uid')])
                unresolved.append('unresolved clause reference ' + target)
    ordered = sorted(disposal, key=atoms_lifted_sort_key_1)
    i = 0
    while i + 1 < len(ordered):
        left = ordered[i]
        right = ordered[i + 1]
        if left.get('scope') == right.get('scope') and left.get('clause') != right.get('clause') and (parents.get(left.get('clause')) == parents.get(right.get('clause'))):
            lraw = known[left.get('clause')].get('text', '')
            tail = atoms_low(lraw)
            connector = 'and_or' if tail.endswith('and/or') else 'and' if tail.endswith('and') else 'or' if tail.endswith('or') else None
            if connector is not None:
                atoms_add(out, ['source_connector_atom', left.get('scope'), left.get('action'), right.get('action'), connector, lraw], [left.get('uid'), right.get('uid')])
                connectors.append([left.get('scope'), left.get('action'), right.get('action'), connector])
                if connector == 'and_or':
                    unresolved.append('and/or connector remains unresolved for ' + left.get('scope'))
        i += 1
    scopes = []
    for action in disposal:
        if action.get('scope') not in scopes:
            scopes.append(action.get('scope'))
    for scope in scopes:
        scoped = []
        for action in disposal:
            if action.get('scope') == scope:
                scoped.append(action)
        supported = True
        for action in scoped:
            found_material = False
            for row in out:
                term = row.get('term')
                if isinstance(term, list) and len(term) > 2 and (term[0] == 'source_material_atom') and (term[2] == action.get('action')):
                    found_material = True
            if not found_material or not atoms_has_target_trigger(action, parents, triggers):
                supported = False
                if not atoms_has_target_trigger(action, parents, triggers):
                    unresolved.append('trigger unresolved for ' + action.get('action'))
        if len(scoped) > 1:
            linked = False
            for connector in connectors:
                if connector[0] == scope and connector[3] in ('and', 'or'):
                    linked = True
            if not linked:
                supported = False
        if supported:
            support = []
            for action in scoped:
                support.append(action.get('uid'))
                clause = action.get('clause')
                while clause is not None:
                    record = known.get(clause)
                    if record is not None:
                        support.append(record.get('uid'))
                    clause = parents.get(clause)
            atoms_add(out, ['source_program_scope_supported', scope], atoms_unique(support))
    return {'statements': out, 'complete': len(atoms_unique(unresolved)) == 0, 'unresolved': atoms_unique(unresolved)}
